import{_ as r,a0 as d,w as i,s,ao as l,I as a,a1 as n,A as p,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/12 - The history of Android","title":"安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代","tag":"The history of Android","desc":""},"relativePath":"The history of Android/12 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/12 - The history of Android.md"};function h(g,o,A,c,f,u){const e=d("Link");return i(),s("div",null,[o[14]||(o[14]=l('<h1 id="安卓編年史-12-android-2-1——動畫的大發現-以及濫用-時代" tabindex="-1">安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代 <a class="header-anchor" href="#安卓編年史-12-android-2-1——動畫的大發現-以及濫用-時代" aria-label="Permalink to “安卓編年史（12）：Android 2.1——動畫的大發現（以及濫用）時代”">​</a></h1><h3 id="android-2-1——動畫的大發現-以及濫用-時代" tabindex="-1">Android 2.1——動畫的大發現（以及濫用）時代 <a class="header-anchor" href="#android-2-1——動畫的大發現-以及濫用-時代" aria-label="Permalink to “Android 2.1——動畫的大發現（以及濫用）時代”">​</a></h3><p>安卓 2.1 隨着 Nexus One 的發佈一同到來，這時距安卓 2.0 的發佈僅僅過了三個月。新系統並不是一個大的更新升級，所以它仍然使用 Éclair（泡芙）這個名稱。安卓的開發以一種聞所未聞的步伐急速進行，在過去的 15 個月中，谷歌平均每兩個半月就發佈一個新版本。</p><p>絕大部分得益於威瑞森在市場營銷上的努力以及“Droid”產品線，安卓日益流行起來。即便如此，這個系統還是被人覺得醜，這時的安卓工程師看起來就幾乎沒有接受過正式的設計培訓，在安卓 2.1 中，他們嘗試着通過在所有能用上的地方大量使用動畫效果，想讓東西看起來更整齊一點。這麼做的結果就是系統看起來拼命想要證明它可以實現動畫效果。許多新增的部分感覺更像是技術的演示而不是為了用户體驗的改善。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/21.png" alt="安卓2.1和2.0中的鎖屏和主屏幕。"></p><p><em>安卓 2.1 和 2.0 中的鎖屏和主屏幕。 [Ron Amadeo 供圖]</em></p><p>安卓 2.0 的旋轉撥號式鎖屏在僅僅在一個版本之後就被踢到路邊去了，取而代之的是和來電界面使用的相同的拉動式標籤式解鎖。鎖屏時鐘嘗試使用了一種獨特的安卓字體，但是相比其它字體來説，它真是醜得可以。</p><p>安卓 2.1 最大的特色之一是“動態壁紙”——可互動的或是動態圖片可以被設置為壁紙。默認的動態壁紙是個灰色正方形組成的大方陣，不斷有藍色，紅色，黃色以及綠色的光點拖着尾巴穿越屏幕。點擊屏幕會使光點以你點擊的位置為中心向四個方向射出。儘管動態壁紙看起來很棒（並且相對 iPhone 而言是個獨特的特性），但動畫背景對電池和處理器而言可不是什麼好事。它似乎讓整個系統的運行都變得有點慢了。</p><p>在主屏幕上，默認的谷歌搜索小部件周圍有了更多空間，並且現在它位於所在行的正中央。頁面指示器現在出現在屏幕底部的左右角落，主屏幕的頁數也從 3 頁變成了 5 頁。底部的應用抽屜標籤被替換為一個正方形方陣組成的圖標，這個（對應用列表的）暗喻直到今天谷歌也還在使用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/21icons.png" alt="圖片展示了安卓2.1和2.0中的應用抽屜設計以及應用的選擇。"></p><p><em>圖片展示了安卓 2.1 和 2.0 中的應用抽屜設計以及應用的選擇。 [Ron Amadeo 供圖]</em></p><p>和新應用抽屜圖標一同到來的還有全新的應用抽屜。應用抽屜不再是以前從屏幕底部上拉的帶標籤容器的樣子，新界面顯示為一個全屏界面。原先的碳纖維編織紋理被去掉了，變成了一個純黑背景——這個改變會一直持續到 KitKat。</p><p>谷歌決定添加一個浮動的、半透明的 home 圖標到應用抽屜的底部，好讓人們方便地退出全屏的應用列表界面。這個可以看作是安卓 4.0 中引入的虛擬 home 鍵的前身。</p><p>應用抽屜同樣有個俗氣的圖形效果。在滾動的時候，在應用列表頂部和底部的圖標會向內彎曲並且看起來像是向手機深處移動一樣，有點像星球大戰開場的滾動字幕。</p><p>應用的圖標也有不多的改變。“Amazon MP3”和“Alarm Clock”（鬧鐘）都去掉了前面那個單詞，然後他們就從按字母排序的列表的前兩個位置退了下來。出現了兩個新的應用：新聞和天氣，以及 Google Voice，這是谷歌的通信服務。由於 Nexus One 不是威瑞森的定製機，威瑞森的可視語音郵件被去掉了。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/clo2ck.png" alt="修改後的時鐘應用。"></p><p><em>修改後的時鐘應用。 [Ron Amadeo 供圖]</em></p><p>不止是名稱的更改，時鐘應用還迎來了整體上的重製。點擊時鐘快捷方式不再會打開鬧鐘頁面；取而代之的是去到“桌面時鐘”界面（上方左圖），它帶有一個和壁紙一致的背景。時鐘使用和鎖屏一樣的字體，並從新的新聞和天氣應用中獲取天氣。</p><p>新的鬧鐘頁面清除了許多舊版本中奇怪的設計。模擬時鐘和可選擇的時鐘樣式已經不見了。複選框已經被一個帶綠色亮光的開關所取代，它比“灰色勾選/綠色勾選”更容易理解。儘管可能從快照很難看出來，舊的鬧鐘設計在時間旁同時顯示 AM 和 PM。2.1 的設計裏取消了這一項，只顯示相關的 AM/PM 標記。底部放置了一個數字時鐘，點擊時鐘圖標會將你帶回桌面時鐘界面。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/gallery1.png" alt="安卓2.1和2.0中的相冊和單獨圖片查看界面。"></p><p><em>安卓 2.1 和 2.0 中的相冊和單獨圖片查看界面。 [Ron Amadeo 供圖]</em></p><p>谷歌想要改進安卓外觀的慾望在 2.1 的相冊中最為明顯，這裏幾乎都是大量使用的動畫效果和半透明。當應用打開的時候，單獨的圖片從屏幕頂部飛下並且打亂成小堆組成相冊。當打開相冊的時候，圖片堆各自分離，照片滑開形成方陣的形式。所有你觸摸的東西會彈開，壓縮，以及拉伸，就像是果凍的彈簧片一樣。</p><p>相冊這裏沒有一個“標準”的背景。它會從屏幕上隨機選擇一張圖片並深度模糊，然後作為背景圖片使用。當這張圖片滑出屏幕顯示範圍後，它會重新選擇一張背景圖片，所以背景色調總是會和你的圖片相匹配。</p><p>屏幕的左上角放置了麪包屑導航欄。它顯示你當前的位置，以及你所在位置和主界面之間的任何文件夾——它可以被看作是在安卓 3.0 中即將推出的“向上”按鈕的前身。在右上角是一個相機的鏈接，這還留着相同的在安卓 1.6 中登場的人造皮革設計——兩個設計截然不同。</p><p>而相機是另一個奇怪的、一次性的設計，從來沒有哪個安卓應用間的隨意的 UI 設計差距能有和新的相冊應用間這麼明顯。它並沒有採用安卓的按鈕、菜單、或任何現有的 UI 規範。它甚至在每個界面隱藏了狀態欄——你幾乎不能分辨出你正在盯着的是安卓。</p><p>在單張照片查看視圖，你終於可以在圖片之間滑動切換，從而去掉了短粗的左右箭頭。出於某種原因，這個界面並沒有顏色匹配的背景。它是應用中唯一一個背景為黑色的部分。縮放控制在右上方（仍然沒有兩指捏合縮放），可用命令沿着屏幕的底部排成一行。點擊“菜單”按鈕（虛擬或實體鍵）並不會像所有其他的應用一樣出現一個 2×3 格的方陣——僅僅是底部的一行選項從兩個變成了另外三個選項。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/gallery2.png" alt="充滿動畫效果的相冊應用。"></p><p><em>充滿動畫效果的相冊應用。 [Ron Amadeo 供圖]</em></p><p>上面第一張圖片，顯示了一個相冊視圖。大型相冊的話你可以水平滾動，或使用在屏幕底部的快速滾動條。長按圖片（雖然有點奇怪，或者可以按實體菜單按鈕）會彈出一個“複選框”界面，這時你可以點擊幾張照片同時選中它們。你選中照片之後，你可以批量分享、刪除或旋轉照片。</p><p>這個界面和接下來的單張照片查看界面的菜單是半透明對話氣泡式的，點擊各個按鈕時它們會跳出來。再重複一遍，這和你所看到的正常的安卓體驗規範大相逕庭。相冊還是第一個擁有越界效果（overscroll）的應用之一。當你到達照片牆的底部時，整個界面會向滾動的方向扭曲。</p><p>2.1 的相冊是第一個能同時顯示您雲存儲的 Picasa 照片以及本地照片的客户端。這些照片縮略圖的左下角有白色相機快門圖標。這後來成為了 Google+ Photos。</p><p>之前或之後任何安卓應用程序看起來都不像這個相冊。有很好的理由解釋這是為什麼——它不是谷歌做的！這個應用外包給了 Cooliris，他們看樣子並沒有打算花費精力遵循任何一條現有的安卓 UI 規範。儘管應用是可用的，所有的動畫和效果使它看起來像是隻注重風格而不注重實質的產物。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/newsandweather.png" alt="“新聞和天氣”應用展示了……新聞和天氣。"></p><p><em>“新聞和天氣”應用展示了……新聞和天氣。 [Ron Amadeo 供圖]</em></p><p>來比較下相冊應用和另一個全新的安卓 2.1 應用：新聞和天氣。相冊是個充滿透明動畫效果的匯聚，而新聞和天氣則全是深色漸變和對比色。這個應用提供了桌面時鐘的天氣顯示，它甚至還帶着一個主屏幕小部件。第一張圖顯示的是當前位置的天氣和六天的預報。沿着屏幕頂部排列着一些標籤，城市名稱旁有個小小的“i”按鈕，點擊它會打開温度和降水圖。你可以在圖上滑動以得到指定時間的精確温度和降水信息。</p><p>這個應用裏最大的創新在於可滑動標籤，這個想法最終將成為一個標準的安卓 UI 規範。在天氣之後是一些可由用户定製的新聞標籤，除了點擊標籤切換之外，你還可以在屏幕上水平滑動，標籤也會跟着切換。新聞標籤都顯示着一個新聞標題列表，它們幾乎總是正好截斷到你弄不明白這條新聞講了什麼的程度。當你從這個應用打開一個網頁時，它並不會啓動瀏覽器。相反，它會在應用內打開新聞，帶着個奇怪的白色邊框。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/04/ccccombo.jpg" alt="谷歌地圖的一些實驗性功能，新的小部件設計，Google Voice裏我們能接觸到的唯一一個界面，以及新的帶標籤的音樂界面設計。"></p><p><em>谷歌地圖的一些實驗性功能，新的小部件設計，Google Voice 裏我們能接觸到的唯一一個界面，以及新的帶標籤的音樂界面設計。 [Ron Amadeo 供圖]</em></p><p>安卓 2.1 裏的小部件全部經過了重新設計，幾乎所有東西都帶有黑色漸變，空間利用上也更加合理。時鐘變回了一個圓，日曆的頂部加上了藍色，着讓它和應用變得更加相似。Google Voice 可以啓動，但是登錄已經失效了——這是你現在能看到的所有東西了。</p><p>人們經常忽視的音樂應用有個小更新。四個按鈕的主界面被完全去除，並且在屏幕頂部添加了每個音樂顯示模式的標籤。這意味着在打開應用的時候，你就能直接看到音樂列表，而不是一個導航頁。不同於新聞和天氣應用裏的標籤，這些新增的標籤不能滑動切換。</p><hr><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg" alt="Ron Amadeo"></p>',42)),a("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...o[0]||(o[0]=[t("Ron Amadeo",-1)])]),_:1}),o[2]||(o[2]=t(" / Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。 ",-1)),n(e,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...o[1]||(o[1]=[t("@RonAmadeo",-1)])]),_:1})]),o[15]||(o[15]=a("hr",null,null,-1)),a("p",null,[o[4]||(o[4]=t("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/12/"},{default:p(()=>[...o[3]||(o[3]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/12/",-1)])]),_:1})]),a("p",null,[o[7]||(o[7]=t("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:p(()=>[...o[5]||(o[5]=[t("alim0x",-1)])]),_:1}),o[8]||(o[8]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...o[6]||(o[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[o[11]||(o[11]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...o[9]||(o[9]=[t("LCTT",-1)])]),_:1}),o[12]||(o[12]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...o[10]||(o[10]=[t("Linux中國",-1)])]),_:1}),o[13]||(o[13]=t(" 榮譽推出",-1))])])}const w=r(m,[["render",h]]);export{C as __pageData,w as default};
